        assertEquals(true, connection instanceof HttpConnection.CookieStore);

        cookieStore.setCookies(null);

        Thread.sleep(5000);

        String cookies = cookieStore.getCookieString();

        assertEquals(cookies, "some-cookies", "Unexpected cookies");
    }

